<?php

namespace App\Support;

use App\Models\Admin;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Str;

/**
 * Emails an admin their temporary password. The password is generated by the
 * server, never typed by a person, and must be changed at the first sign-in.
 */
class AdminMail
{
    public static function generatePassword(): string
    {
        // Letters and digits only, so it survives being copied from an email.
        return Str::password(16, true, true, false, false);
    }

    public static function panelLoginUrl(): string
    {
        return rtrim((string) (config('cors.allowed_origins')[0] ?? ''), '/ ').'/login';
    }

    /** @return bool whether the email was handed to the mail system */
    public static function sendPassword(Admin $admin, string $plain, bool $isReset): bool
    {
        if (blank($admin->email)) {
            return false;
        }

        $intro = $isReset
            ? 'A super admin has reset the password for your Mora Lenz admin account.'
            : 'A Mora Lenz admin account has been created for you.';

        try {
            Mail::raw(
                "Hello {$admin->name},\n\n"
                ."{$intro}\n\n"
                .'Sign in:    '.static::panelLoginUrl()."\n"
                ."Username:   {$admin->username}\n"
                ."Password:   {$plain}\n\n"
                .'This is a temporary password. You will be asked to choose your own '
                ."the first time you sign in. Do not share it with anyone.\n",
                fn ($mail) => $mail->to($admin->email, $admin->name)
                    ->subject($isReset ? 'Your Mora Lenz admin password was reset' : 'Your Mora Lenz admin account')
            );

            return true;
        } catch (\Throwable $e) {
            Log::warning('Admin password email could not be sent.', [
                'admin_id' => $admin->id,
                'error' => $e->getMessage(),
            ]);

            return false;
        }
    }
}
